const nrm=t=>String(t).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,' ').trim();
(()=>{const have={};Object.keys(E).forEach(k=>have[nrm(E[k].n)]=k);
  LIB_X.forEach(x=>{const k=have[nrm(x.n)];if(k){Object.assign(E[k],{g:x.g,s:x.s,t:x.t});if(x.pat!=='Otros'&&!E[k].pat)E[k].pat=x.pat;return;}
    E[x.id]={n:x.n,pat:x.pat,mus:x.s,eq:x.eq,lvl:x.lvl,g:x.g,s:x.s,t:x.t};});})();
function gOf(e){if(e.g)return e.g;const p=e.pat||'',m=e.mus||'';
  if(/Estiramiento/.test(p))return 'Estiramiento';
  if(/Movilidad|Activación|Respiración/.test(p))return 'Calentamiento';
  if(/Pecho/.test(m))return 'Pecho';if(/Espalda|Dorsal|Escápula/.test(m))return 'Espalda';
  if(/Hombro|Deltoide|Trapecio|Manguito/.test(m))return 'Hombro';if(/Bíceps|Tríceps/.test(m))return 'Brazos';
  if(/Glúteo/.test(m)&&!/Cuádriceps/.test(m))return 'Glúteo';
  if(/Cuádriceps|Isquio|Gemelos|Pierna|Cadera/.test(m))return 'Pierna';if(/Abdomen/.test(m))return 'Core';return 'Otros';}
Object.keys(E).forEach(k=>{if(!E[k].g||E[k].g==='Otros')E[k].g=gOf(E[k]);});
