function rtWarn(d){
  const w=[],m=rtBlock(d,'main'),a=rtBlock(d,'acc');if(!m||!a)return w;
  const all=m.items.concat(a.items,...d.blocks.filter(x=>x.cust).map(x=>x.items)),exs=all.map(x=>E[x.ex]||{});
  if(all.length>6)w.push('Más de 6 ejercicios (core incluido).');
  if(m.items.length>2)w.push('Más de 2 básicos.');
  const leg=exs.some(e=>['Sentadilla','Bisagra de cadera','Extensión de rodilla','Curl femoral','Zancada','Gemelos','Glúteo aislado','Abducción'].includes(e.pat));
  const core=exs.some(e=>e.pat==='Core');
  if(leg&&!core&&!/brazos/i.test(d.name))w.push('Día de pierna sin core.');
  const seen={};all.forEach(x=>{const e=E[x.ex]||{};if(!e.pat||['Core','Gemelos','Flexión de codo','Extensión de codo','Elevación lateral','Deltoide posterior'].includes(e.pat))return;seen[e.pat]=(seen[e.pat]||0)+1;});
  Object.keys(seen).forEach(p=>{if(seen[p]>1)w.push('Patrón repetido: '+p+'.');});
  return w;
}
