const fOpts=(kind,sel)=>`<option value="">(Sin carpeta)</option>`+RT.fo.filter(f=>f.kind===kind).map(f=>({id:f.id,p:fpath(f.id)})).sort((a,b)=>a.p.localeCompare(b.p)).map(f=>`<option value="${f.id}"${f.id===sel?' selected':''}>${esc(f.p)}</option>`).join('');
