/* ---------- cliente: cargar su rutina real ---------- */
async function loadClientRoutine(uid){
  await rtLoadCx();
  try{const r=await DB.routine(uid);if(r&&r.days&&r.days.length){DAYS.length=0;r.days.forEach(d=>DAYS.push(d));}cxSync();}catch(e){console.warn('routine',e);}
}

/* ---------- arrastrar ejercicios (entre Central y Accesorios, reordenar, y desde la biblioteca) ---------- */
function rtMoveItem(di,fb,fi,tb,ti){
  const d=RT.days[di],B0=rtBlock(d,fb),B1=rtBlock(d,tb);if(!B0||!B1||!B0.items[fi])return;
  const okb=k=>k==='main'||k==='acc'||String(k).indexOf('x_')===0,cross=fb!==tb;if(cross&&!(okb(fb)&&okb(tb)))return;
  const it=B0.items.splice(fi,1)[0];if(!cross&&fi<ti)ti--;
  if(cross){const toM=tb==='main';if(it.kind==='basic'||it.kind==='acc'){it.kind=toM?'basic':'acc';
    if(!it.tempo||it.tempo===(toM?RDEF.tempo:'3-0-1-0'))it.tempo=toM?'3-0-1-0':RDEF.tempo;
    if(!it.rest||+it.rest===(toM?RDEF.rest:120))it.rest=toM?120:RDEF.rest;}}
  B1.items.splice(Math.max(0,Math.min(ti,B1.items.length)),0,it);RT.dirty=true;rtShow();
}
RT.dr=null;RT.dl=null;RT.dt=null;
function rtDropClear(){document.querySelectorAll('.rtdrop,.rtbefore,.rtafter,.rtdragging').forEach(x=>x.classList.remove('rtdrop','rtbefore','rtafter','rtdragging'));}
document.addEventListener('dragstart',e=>{
  const g=e.target.closest&&e.target.closest('[data-rtdrag]'),l=e.target.closest&&e.target.closest('[data-libdrag]');
  if(g){const [di,bk,ii]=g.dataset.rtdrag.split('|');RT.dr={di:+di,bk,ii:+ii};RT.dl=null;try{e.dataTransfer.setData('text/plain','rt');e.dataTransfer.effectAllowed='move';const r=g.closest('.rtit');if(r){e.dataTransfer.setDragImage(r,24,24);r.classList.add('rtdragging');}}catch(x){}}
  else if(l){RT.dl=l.dataset.libdrag;RT.dr=null;try{e.dataTransfer.setData('text/plain','lib');e.dataTransfer.effectAllowed='copy';}catch(x){}}
},true);
document.addEventListener('dragover',e=>{
  if(!RT.dr&&!RT.dl)return;const sec=e.target.closest&&e.target.closest('.rtsec[data-dropbk]');if(!sec)return;
  const bk=sec.dataset.dropbk;
  if(RT.dr&&RT.dr.bk!==bk&&!((RT.dr.bk==='main'||RT.dr.bk==='acc')&&(bk==='main'||bk==='acc')))return;
  e.preventDefault();rtDropClear();sec.classList.add('rtdrop');
  const it=e.target.closest('.rtit');let idx=rtBlock(RT.days[RT.sel],bk).items.length;
  if(it){const [,,ii]=it.dataset.rtit.split('|'),r=it.getBoundingClientRect(),after=e.clientY>r.top+r.height/2;idx=+ii+(after?1:0);it.classList.add(after?'rtafter':'rtbefore');}
  RT.dt={bk,idx};
},true);
document.addEventListener('drop',e=>{
  if(!RT.dr&&!RT.dl)return;const sec=e.target.closest&&e.target.closest('.rtsec[data-dropbk]');if(!sec||!RT.dt){rtDropClear();return;}
  e.preventDefault();const {bk,idx}=RT.dt,di=RT.sel;
  if(RT.dr){const f=RT.dr;RT.dr=null;rtDropClear();rtMoveItem(f.di,f.bk,f.ii,bk,idx);}
  else if(RT.dl){const id=RT.dl;RT.dl=null;rtDropClear();rtAddItem(di,bk,id);const b=rtBlock(RT.days[di],bk);b.items.splice(idx,0,b.items.pop());RT.dirty=true;rtShow();}
  RT.dt=null;
},true);
document.addEventListener('dragend',()=>{RT.dr=null;RT.dl=null;RT.dt=null;rtDropClear();},true);

async function rtLoadCir(){RT.cir=null;try{const r=await DB.circuits();RT.cir=(r||[]).map(x=>({id:x.id,name:x.name,cfg:x.cfg}));}catch(e){console.warn('circuits',e);RT.cir=[];}rtShow();}

/* ===== Ejercicios SIN VIDEO: eliminados de la app (21 nov) ===== */
const E_SIN={};
(function(){
  Object.keys(E).forEach(k=>{const e=E[k];if(e&&e.n&&!e.yt&&!/\(ANTIGUO\)/i.test(e.n)&&!/^x_/.test(k)){E_SIN[k]=e;delete E[k];}});
  const alt=k=>{const o=E_SIN[k];if(!o)return null;
    if(o.pat==='Respiración'||/^Movilidad/.test(o.pat||'')||o.pat==='Activación escapular'||o.pat==='Trapecio')return null;
    const c=Object.keys(E).filter(x=>E[x].yt&&!/\(ANTIGUO\)/i.test(E[x].n)&&E[x].pat===o.pat);
    const r=c.find(x=>E[x].eq===o.eq)||c[0];return r||null;};
  window.exClean=function(days){
    if(!Array.isArray(days))return days;
    days.forEach(d=>(d.blocks||[]).forEach(b=>{if(!Array.isArray(b.items))return;
      b.items=b.items.map(it=>{if(!it||!it.ex||E[it.ex]||!E_SIN[it.ex])return it;const a=alt(it.ex);if(!a)return null;it.ex=a;return it;}).filter(Boolean);}));
    return days;};
  exClean(DAYS);
  RT_SEED.forEach(s=>exClean(s.days));
  const r0=DB.routine,t0=DB.templates;
  DB.routine=async function(){const r=await r0.apply(DB,arguments);if(r&&r.days)exClean(r.days);return r;};
  DB.templates=async function(){const r=await t0.apply(DB,arguments);(r||[]).forEach(x=>exClean(x.days));return r;};
})();
